from ta_messaging.messages_subscriber import MessagesSubscriber


class MessagesCounter(MessagesSubscriber):
    """
    Class with functions to online count the messages of given type
    """
    def __init__(self):
        super(MessagesCounter, self).__init__()
        self.msgs = {}

    def count(self, message_type):
        """

        :param message_type:
        :return: number of given type messages
        """
        queue_size = self.queue_for_messages.qsize()
        if queue_size:
            print('Queue for messages not emptied, it contains: {} messages, please try again later to get reliable result'.format(queue_size))
        return self.msgs.get(message_type, 0)

    def clear_counter(self):
        """
        Clears the counter
        """
        self.msgs = {}

    def on_new_message(self, message):
        """
        Increments message occurrence number
        :param message:
        :return:
        """
        type_of_message = message.message_type
        previous_number_of_such_msgs = self.msgs.get(type_of_message, 0)
        current_number_of_such_msgs = previous_number_of_such_msgs + 1
        self.msgs[type_of_message] = current_number_of_such_msgs
